[tikz]
\begin{tikzpicture}[scale=0.85]
\draw[gray!30,very thin,xstep=0.5,ystep=0.25] (0,0) grid (8,4.2);
\draw[->] (0,0)--(0,5.4);
\draw[->] (0,0)--(8.6,0);
\foreach \y in {1,2,3,4} {\draw (-0.12,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\y00$};}
