\foreach \x in {1,2,3,4,5,6,7,8} {\draw (\x,-0.12)--(\x,0); \node[below,font=\scriptsize] at (\x,-0.15) {$\x$};}
\draw[red,thick] (0,0)--(8,4);
\draw[blue,dashed,->] (0,2.25)--(4.5,2.25);
\draw[blue,dashed,->] (4.5,2.25)--(4.5,0);
\fill[blue] (4.5,2.25) circle (2pt);
\node[below,font=\tiny,fill=white,inner sep=1pt] at (4.5,-0.15) {$4.5$};
\node[rotate=90,font=\scriptsize] at (-2,2) {Interest (dollars)};
\node[below,font=\scriptsize] at (4,-1) {Time (years)};
\node[font=\scriptsize] at (4,5.1) {Laptop fund interest};
